<?php
namespace App\Http\Controllers\Api\V1; use App\Domain\Finance\Services\VendorResolver; use App\Http\Controllers\Controller; use App\Models\TaxInvoice; use Illuminate\Http\{JsonResponse,Request}; class InvoiceController extends Controller { public function __construct(private readonly VendorResolver $vendors){} public function sellerIndex(Request $r):JsonResponse{$v=$this->vendors->forUser($r->user());$rows=TaxInvoice::query()->where('vendor_id',$v->id)->with(['order','vendor','creditNotes'])->latest('issued_at')->limit(200)->get();return response()->json(['data'=>$rows->map(/** Inline callback for this operation. */ fn($x)=>$this->row($x,false))->all()]);} public function sellerShow(Request $r,TaxInvoice $invoice):JsonResponse{$v=$this->vendors->forUser($r->user());abort_unless((int)$invoice->vendor_id===(int)$v->id,404);$invoice->load(['order','vendor','items','creditNotes.items']);return response()->json(['data'=>$this->row($invoice,true)]);} public function index(Request $r):JsonResponse{$rows=TaxInvoice::query()->whereHas('order',/** Inline callback for this operation. */ fn($q)=>$q->where('user_id',$r->user()->id))->with(['order','vendor','creditNotes'])->latest('issued_at')->get();return response()->json(['data'=>$rows->map(/** Inline callback for this operation. */ fn($x)=>$this->row($x,false))->all()]);} public function show(Request $r,TaxInvoice $invoice):JsonResponse{abort_unless($invoice->order()->where('user_id',$r->user()->id)->exists(),404);$invoice->load(['items','creditNotes.items']);return response()->json(['data'=>$this->row($invoice,true)]);} private function row($x,bool $full):array{$base=['id'=>$x->public_id,'number'=>$x->invoice_number,'orderId'=>$x->order?->public_id,'seller'=>$x->vendor?->name??($x->seller_snapshot['name']??'Marketplace'),'currency'=>$x->currency,'issuedAt'=>$x->issued_at?->toIso8601String(),'totals'=>['subtotalMinor'=>$x->subtotal_minor,'discountMinor'=>$x->discount_minor,'taxableMinor'=>$x->taxable_minor,'taxMinor'=>$x->tax_minor,'totalMinor'=>$x->total_minor],'creditNotes'=>$x->creditNotes->map(/** Inline callback for this operation. */ fn($c)=>['id'=>$c->public_id,'number'=>$c->credit_note_number,'taxMinor'=>$c->tax_minor,'totalMinor'=>$c->total_minor,'issuedAt'=>$c->issued_at?->toIso8601String()])->all()];if($full)$base+=['sellerSnapshot'=>$x->seller_snapshot,'buyerSnapshot'=>$x->buyer_snapshot,'items'=>$x->items->map(/** Inline callback for this operation. */ fn($i)=>['kind'=>$i->kind,'description'=>$i->description,'sku'=>$i->sku,'quantity'=>$i->quantity,'grossMinor'=>$i->gross_minor,'discountMinor'=>$i->discount_minor,'taxableMinor'=>$i->taxable_minor,'taxMinor'=>$i->tax_minor,'totalMinor'=>$i->total_minor,'taxBreakdown'=>$i->tax_breakdown])->all()];return $base;} }